'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/dialog/md-gb-dialog.js';
import {DialogElement} from '@material/web/labs/gb/components/dialog/dialog-element.js';

/**
 * A Material Design dialog component. Wraps <md-gb-dialog>.
 * Docs: https://material-web.dev/3.0/components/dialog/
 */
export const MdDialog = createComponent({
  react: React,
  tagName: 'md-gb-dialog',
  elementClass: DialogElement,
  events: {
    onCancel: 'cancel' as EventName<Event>,
    onClose: 'close' as EventName<Event>,
    onClosed: 'closed' as EventName<Event>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
  },
});

export type MdDialogProps = React.ComponentProps<typeof MdDialog>;
